// ─── File: TransferOutboxDemo.java ───
// Runnable demo. In a real project each class lives in its own file.
// Simulates the Outbox pattern: atomic DB+outbox write, then a relay to Kafka.
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class TransferOutboxDemo {
    private static final Logger log = Logger.getLogger("Outbox");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository accountRepo = new AccountRepository();
        OutboxRepository outboxRepo = new OutboxRepository();
        SimulatedKafka kafka = new SimulatedKafka();

        TransferService service = new TransferService(accountRepo, outboxRepo);
        BigDecimal rentAmount = new BigDecimal("50000");

        // Atomic: debit + credit + outbox row all in ONE local transaction.
        service.transfer("SAV2001", "CUR3001", rentAmount);

        // The relay runs separately. Simulate it crashing and restarting.
        OutboxRelay relay = new OutboxRelay(outboxRepo, kafka);
        log.info("--- relay pass 1 (crashes after send, before mark) ---");
        relay.drainButCrashBeforeMark();   // at-least-once: publishes, does not mark
        log.info("--- relay pass 2 (restarts, re-publishes same row) ---");
        relay.drain();                      // re-publishes, then marks published

        log.info(() -> "Kafka received " + kafka.count() + " messages (duplicate expected)");
        log.info("Consumer must be idempotent to ignore the duplicate by event id.");
    }
}

// ─── Would be in model/Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
    }
    void debit(BigDecimal amt) {
        if (balance.compareTo(amt) < 0) throw new IllegalStateException("Insufficient funds");
        balance = balance.subtract(amt);
    }
    void credit(BigDecimal amt) { balance = balance.add(amt); }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in model/OutboxEvent.java ───
class OutboxEvent {
    private final UUID id;
    private final String aggregateType;
    private final String aggregateId;
    private final String eventType;
    private final String payload;
    private boolean published;
    OutboxEvent(String aggregateType, String aggregateId, String eventType, String payload) {
        this.id = UUID.randomUUID();
        this.aggregateType = aggregateType; this.aggregateId = aggregateId;
        this.eventType = eventType; this.payload = payload; this.published = false;
    }
    UUID getId() { return id; }
    String getAggregateId() { return aggregateId; }
    String getEventType() { return eventType; }
    String getPayload() { return payload; }
    boolean isPublished() { return published; }
    void markPublished() { published = true; }
}

