class AccountRepository {
    private final Map<String, Account> store = new HashMap<>();
    AccountRepository() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        store.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
    }
    Account findById(String id) { return store.get(id); }
    void save(Account a) { store.put(a.getAccountId(), a); }
}

// ─── Would be in repository/OutboxRepository.java ───
class OutboxRepository {
    private final List<OutboxEvent> store = new ArrayList<>();
    void save(OutboxEvent e) { store.add(e); }
    List<OutboxEvent> findUnpublished() {
        List<OutboxEvent> out = new ArrayList<>();
        for (OutboxEvent e : store) if (!e.isPublished()) out.add(e);
        return out;
    }
}

// ─── Would be in service/TransferService.java ───
class TransferService {
    private static final Logger log = Logger.getLogger("Outbox");
    private final AccountRepository accountRepo;
    private final OutboxRepository outboxRepo;
    TransferService(AccountRepository accountRepo, OutboxRepository outboxRepo) {
        this.accountRepo = accountRepo; this.outboxRepo = outboxRepo;
    }
    // @Transactional — in real Spring this wraps BOTH saves in one DB transaction.
    void transfer(String fromId, String toId, BigDecimal amount) {
        Account from = accountRepo.findById(fromId);
        Account to = accountRepo.findById(toId);
        from.debit(amount);
        to.credit(amount);
        accountRepo.save(from);
        accountRepo.save(to);
        // SAME transaction: record the event in the outbox. No Kafka call here.
        String payload = "{\"from\":\"" + fromId + "\",\"to\":\"" + toId
                + "\",\"amount\":" + amount + "}";
        OutboxEvent evt = new OutboxEvent("Transfer", fromId, "TransferCompleted", payload);
        outboxRepo.save(evt);
        log.info(() -> "Committed debit+credit+outbox atomically for " + amount
                + " from " + fromId + " to " + toId);
    }
}

// ─── Would be in service/OutboxRelay.java (replaced by Debezium CDC in prod) ───
class OutboxRelay {
    private static final Logger log = Logger.getLogger("Outbox");
    private final OutboxRepository outboxRepo;
    private final SimulatedKafka kafka;
    OutboxRelay(OutboxRepository outboxRepo, SimulatedKafka kafka) {
        this.outboxRepo = outboxRepo; this.kafka = kafka;
    }
    void drain() {
        for (OutboxEvent e : outboxRepo.findUnpublished()) {
            kafka.send(e.getAggregateId(), e.getPayload());
            e.markPublished();
            log.info(() -> "Relay published and marked " + e.getId());
        }
    }
    void drainButCrashBeforeMark() {
        for (OutboxEvent e : outboxRepo.findUnpublished()) {
            kafka.send(e.getAggregateId(), e.getPayload());
            log.warning(() -> "Relay sent " + e.getId() + " then CRASHED before marking");
            return; // crash before markPublished — row stays unpublished
        }
    }
}

// ─── Would be in config/SimulatedKafka.java ───
class SimulatedKafka {
    private static final Logger log = Logger.getLogger("Outbox");
    private int count = 0;
    void send(String key, String payload) {
        count++;
        log.info(() -> "KAFKA topic=transfer.events key=" + key + " value=" + payload);
    }
    int count() { return count; }
}

// ─── Would be in config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
